WITH lines AS (SELECT id, log_ts, level, latency_ms, key, value FROM app_logs LATERAL VIEW EXPLODE(context) li AS key, value) SELECT CASE WHEN latency_ms >= 2022 THEN 'PREMIUM' ELSE 'STANDARD' END AS latency_ms_tier, key, DATE_TRUNC('HOUR', log_ts) AS hour_window, SUM(CASE WHEN level = 'ERROR' THEN latency_ms ELSE 0 END) AS error_latency_ms, COUNT_IF(level = 'INFO') AS info_events, SORT_ARRAY(COLLECT_SET(key)) AS key_list, COUNT(DISTINCT id) AS distinct_ids, COUNT_IF(level = 'WARN') AS warn_events, ROUND(SUM(latency_ms) / NULLIF(COUNT(CASE WHEN key = 'region' THEN 1 END), 0), 2) AS latency_ms_per_region, RANK() OVER (PARTITION BY CASE WHEN latency_ms >= 2022 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY ROUND(SUM(latency_ms) / NULLIF(COUNT(CASE WHEN key = 'region' THEN 1 END), 0), 2) DESC) AS latency_ms_per_region_rank FROM lines GROUP BY CASE WHEN latency_ms >= 2022 THEN 'PREMIUM' ELSE 'STANDARD' END, key, DATE_TRUNC('HOUR', log_ts) ORDER BY key DESC;
